    public Object parseMarket(Object asset)
    {
        //
        //     {
        //         "id": "c150e086-1e75-44e6-9c2c-093bb1e93139",
        //         "class": "crypto",
        //         "exchange": "CRYPTO",
        //         "symbol": "BTC/USDT",
        //         "name": "Bitcoin / USD Tether",
        //         "status": "active",
        //         "tradable": true,
        //         "marginable": false,
        //         "maintenance_margin_requirement": 101,
        //         "shortable": false,
        //         "easy_to_borrow": false,
        //         "fractionable": true,
        //         "attributes": [],
        //         "min_order_size": "0.000026873",
        //         "min_trade_increment": "0.000000001",
        //         "price_increment": "1"
        //     }
        //
        Object marketId = this.safeString(asset, "symbol");
        if (Helpers.isTrue(Helpers.isEqual(marketId, null)))
        {
            throw new ExchangeError((String)Helpers.add(this.id, " parseMarket() missing marketId")) ;
        }
        Object parts = Helpers.split(marketId, "/");
        Object assetClass = this.safeString(asset, "class");
        Object baseId = this.safeString(parts, 0);
        Object quoteId = this.safeString(parts, 1);
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        // Us equity markets do not include quote in symbol.
        // We can safely coerce us_equity quote to USD
        if (Helpers.isTrue(Helpers.isTrue(Helpers.isEqual(quote, null)) && Helpers.isTrue(Helpers.isEqual(assetClass, "us_equity"))))
        {
            quote = "USD";
        }
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        Object status = this.safeString(asset, "status");
        Object active = (Helpers.isEqual(status, "active"));
        Object minAmount = this.safeNumber(asset, "min_order_size");
        Object amount = this.safeNumber(asset, "min_trade_increment");
        Object price = this.safeNumber(asset, "price_increment");
        final Object finalMarketId = marketId;
        final Object finalBase = base;
        final Object finalQuote = quote;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", finalMarketId );
            put( "symbol", symbol );
            put( "base", finalBase );
            put( "quote", finalQuote );
            put( "settle", null );
            put( "baseId", baseId );
            put( "quoteId", quoteId );
            put( "settleId", null );
            put( "type", "spot" );
            put( "spot", true );
            put( "margin", null );
            put( "swap", false );
            put( "future", false );
            put( "option", false );
            put( "active", active );
            put( "contract", false );
            put( "linear", null );
            put( "inverse", null );
            put( "contractSize", null );
            put( "expiry", null );
            put( "expiryDatetime", null );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", amount );
                put( "price", price );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", minAmount );
                    put( "max", null );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "created", null );
            put( "info", asset );
        }});
    }

